import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const o="/screenshots/failure-clusters.png",g=JSON.parse('{"title":"Triage a run gone red","description":"When most of a Playwright run goes red, it is usually two or three causes, not forty bugs. Collapse the failures into clusters, rule out the environment, triage each cause once, then confirm the fix.","frontmatter":{"title":"Triage a run gone red","description":"When most of a Playwright run goes red, it is usually two or three causes, not forty bugs. Collapse the failures into clusters, rule out the environment, triage each cause once, then confirm the fix.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/recipes/mass-failure.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/recipes/mass-failure.html"}],["meta",{"property":"og:title","content":"Triage a run gone red | Piwi Dashboard"}],["meta",{"property":"og:description","content":"When most of a Playwright run goes red, it is usually two or three causes, not forty bugs. Collapse the failures into clusters, rule out the environment, triage each cause once, then confirm the fix."}]]},"headers":[],"relativePath":"recipes/mass-failure.md","filePath":"recipes/mass-failure.md","lastUpdated":1790630671000}'),n={name:"recipes/mass-failure.md"};function i(l,e,h,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="forty-tests-are-red-—-where-do-i-start" tabindex="-1">Forty tests are red — where do I start? <a class="header-anchor" href="#forty-tests-are-red-—-where-do-i-start" aria-label="Permalink to &quot;Forty tests are red — where do I start?&quot;">​</a></h1><p>Almost never with forty bugs. A run that goes broadly red is usually two or three causes wearing forty costumes: an environment that didn&#39;t come up, an auth change, one shared component, one bad worker. The job is to collapse the list before reading any stack traces.</p><h2 id="_1-read-the-clusters-not-the-tests" tabindex="-1">1. Read the clusters, not the tests <a class="header-anchor" href="#_1-read-the-clusters-not-the-tests" aria-label="Permalink to &quot;1. Read the clusters, not the tests&quot;">​</a></h2><p>Failures sharing an <strong>error fingerprint</strong> are grouped automatically, so the run tells you <em>&quot;40 failures, 3 root causes&quot;</em> before you open anything.</p><figure><img src="'+o+'" alt="Failure clusters tab grouping failures by normalized error signature"><figcaption>The Failure clusters tab — one row per root cause, with error type, occurrence count, and triage status.</figcaption></figure><p>The grouping is always on and needs no configuration; <a href="/features/failure-clusters.html#how-failures-are-grouped">How failures are grouped</a> explains what the fingerprint masks.</p><h2 id="_2-rule-out-the-boring-causes-first" tabindex="-1">2. Rule out the boring causes first <a class="header-anchor" href="#_2-rule-out-the-boring-causes-first" aria-label="Permalink to &quot;2. Rule out the boring causes first&quot;">​</a></h2><p>Before treating any cluster as a product bug, check the two heuristics on the run&#39;s failure groups:</p><ul><li><strong>Worker correlation</strong> — if a cluster&#39;s failures are concentrated on one worker, you&#39;re looking at a misbehaving worker, not forty broken tests.</li><li><strong>Flaky share</strong> — a cluster made up largely of known-flaky tests is noise riding on a bad run.</li></ul><p>An environment that never came up has a signature of its own: everything fails, fast, on a navigation or connection error. That&#39;s one cluster, one fix, and no test code involved.</p><h2 id="_3-triage-each-cluster-once" tabindex="-1">3. Triage each cluster once <a class="header-anchor" href="#_3-triage-each-cluster-once" aria-label="Permalink to &quot;3. Triage each cluster once&quot;">​</a></h2><p>A cluster page puts the whole investigation on one screen: the situation block across every test that shares the failure, the occurrence sparkline, what changed since the last passing run, and a <a href="/features/failure-clusters.html#the-state-line">state line</a> with <strong>Triage</strong> beside it, which sets one status (open, resolved or ignored), a note and an assignee for the entire group. The affected tests and their evidence follow. Forty tests, three decisions.</p><p>Clusters stay open across runs, so the next red build attaches to the same row rather than starting the conversation over.</p><h2 id="_4-confirm-the-fix-actually-landed" tabindex="-1">4. Confirm the fix actually landed <a class="header-anchor" href="#_4-confirm-the-fix-actually-landed" aria-label="Permalink to &quot;4. Confirm the fix actually landed&quot;">​</a></h2><p>When a later run executes every test a cluster covers and they all pass, Piwi records the fix. The run doesn&#39;t have to be a full one: re-running just the affected tests and seeing them all pass closes the cluster too. The three verdicts, <em>stopped failing</em>, <em>diagnosis verified</em> and <em>regressed</em>, are explained on <a href="/features/failure-clusters.html#did-the-fix-work">Did the fix work?</a>.</p><h2 id="optional-let-a-model-do-the-first-pass" tabindex="-1">Optional: let a model do the first pass <a class="header-anchor" href="#optional-let-a-model-do-the-first-pass" aria-label="Permalink to &quot;Optional: let a model do the first pass&quot;">​</a></h2><p>With <a href="/features/ai-diagnosis.html">AI diagnosis</a> configured, each cluster gets an explanation read against your actual git diff since the last green run, and any suggested patch is validated against your source before it&#39;s shown. It&#39;s off by default and works with a local model — the point is that clustering has already decided <em>what</em> is worth diagnosing, so the model runs a few times per run, not forty.</p><p>Configuring an <strong>embedding</strong> role additionally merges clusters that are the same root cause phrased differently. Without one, clustering stays purely deterministic — still useful, just less aggressive about collapsing near-duplicates.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>From your agent.</strong> <code>get_failure_groups</code> over the <a href="/features/mcp.html">MCP server</a> returns a run&#39;s failures grouped by cluster with the worker correlation included, and <code>get_test_case_context</code> pulls the evidence behind a single failure — steps, console, network, SCM diff. No install; the server is part of the dashboard.</p><p><strong>From a script.</strong> The same grouping is available over the REST API if you&#39;d rather post a summary into your own channel — see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>Before anyone opens anything.</strong> Subscribe to the <code>cluster.new</code> <a href="/features/notifications.html">notification</a> event instead of <code>run.failed</code>: you hear once when a genuinely new root cause appears, not on every red build, and the payload carries a sample error excerpt and the affected cases.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/failure-clusters.html">Failure clusters &amp; the inbox</a>: how failures are grouped, and whether the fix worked</li><li><a href="/features/ai-diagnosis.html">AI diagnosis</a>: semantic merging and the explanation of a cluster</li><li><a href="./regression-or-flaky.html">Regression or flake?</a> — when it&#39;s one test rather than forty</li><li><a href="/guide/concepts.html">Core concepts</a> — <em>cluster</em>, <em>fingerprint</em>, <em>baseline</em></li></ul>',24)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
